import{_ as n,C as o,o as i,c as l,E as r,a3 as h,w as c,j as t,a}from"./chunks/framework.DKrWOZ-k.js";const u="/versions/v0.19.96/screens/devices/m2cv.png",p="/versions/v0.19.96/screens/devices/m2cv-gate.png",O=JSON.parse('{"title":"M2CV","description":"","frontmatter":{"title":"M2CV","pageClass":"device-doc"},"headers":[],"relativePath":"devices/m2cv.md","filePath":"devices/m2cv.md"}'),v={name:"devices/m2cv.md"};function m(g,e,f,b,_,T){const s=o("DeviceHeading"),d=o("ManualRelated");return i(),l("div",null,[r(s,{slug:"m2cv",title:"M2CV"}),e[1]||(e[1]=h('<p>MIDI to control voltage</p><p><img src="'+u+'" alt="M2CV: MODE AUTO, two voices playing." class="screen"></p><p>The outputs are named as on the CV16: <strong>P1</strong> pitch, <strong>G1</strong> gate and <strong>V1</strong> velocity for voice 1, and so on. <strong>CLK</strong> pulses with the clock.</p><p><img src="'+p+'" alt="M2CV in GATE mode, a C major chord" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Play a modular synth from MIDI through the <a href="/versions/v0.19.96/cv16/">CV16</a> module: up to four voices, or gates for drums.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: every gate closes and the outputs stop following MIDI. See <a href="/versions/v0.19.96/devices/#bypass">BYPASS</a>.</td></tr><tr><td>MODE</td><td>AUTO – GATE</td><td>How notes are shared out over the outputs.</td></tr><tr><td>ALGO</td><td>NONE – HIGH VEL</td><td>Which voice a new note takes when all four are busy. <strong>AUTO</strong> only.</td></tr></tbody></table></div><h2 id="parameter-values" tabindex="-1">Parameter values <a class="header-anchor" href="#parameter-values" aria-label="Permalink to &quot;Parameter values&quot;">​</a></h2><h3 id="mode" tabindex="-1">MODE <a class="header-anchor" href="#mode" aria-label="Permalink to &quot;MODE&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td>AUTO</td><td>Up to four voices. Each new note takes the first free voice, from any channel.</td></tr><tr><td>CHANNEL</td><td>Channels 1–4 each play one voice, one note at a time. Other channels are ignored.</td></tr><tr><td>GATE</td><td>Notes open gates, for drums: C2 opens output 1, C#2 output 2, up to D3 on output 15. Higher and lower notes repeat the pattern every 16 notes.</td></tr></tbody></table><h3 id="algo" tabindex="-1">ALGO <a class="header-anchor" href="#algo" aria-label="Permalink to &quot;ALGO&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Value</th><th>What it does</th></tr></thead><tbody><tr><td>NONE</td><td>The new note is ignored.</td></tr><tr><td>OLDEST</td><td>Takes the voice held longest.</td></tr><tr><td>NEWEST</td><td>Takes the voice played last.</td></tr><tr><td>LOWEST</td><td>Takes the lowest note.</td></tr><tr><td>HIGHEST</td><td>Takes the highest note.</td></tr><tr><td>LOW VEL</td><td>Takes the softest note.</td></tr><tr><td>HIGH VEL</td><td>Takes the loudest note.</td></tr></tbody></table>',13)),r(d,null,{default:c(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/v0.19.96/racks/"},"Racks"),a(" — build a chain of devices")]),t("li",null,[t("a",{href:"/versions/v0.19.96/concepts/mapping"},"Mapping"),a(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/versions/v0.19.96/concepts/modulation"},"Modulation"),a(" — move a setting while you play")])],-1)])]),_:1})])}const y=n(v,[["render",m]]);export{O as __pageData,y as default};
